type MutableGeneration = {
	objectId: StorageObjectId;
	generationId: GenerationId;
	baseExpectedHead: ExpectedHead;
	closureDigest: GenerationRecord["closureDigest"];
	closure: GenerationRef[];
	state: GenerationRecord["state"];
