290→	public putCachedBlob(input: {
		objectId: StorageObjectId;
		generationId: GenerationId;
		digest: BlobDigest;
		bytes: Uint8Array;
	}): StoreResult<{ inserted: boolean }> {
		if (typeof input !== "object" || input === null) return rejected("INVALID_ARGUMENT");
